#include <cuda_runtime.h>
#include <stdint.h>
__device__ __forceinline__ uint32_t prmt(uint32_t a, uint32_t b, uint32_t sel) {
  uint32_t d;
  asm("prmt.b32 %0, %1, %2, %3;" : "=r"(d) : "r"(a), "r"(b), "r"(sel));
  return d;
}

__device__ __forceinline__ uint32_t lop3_sel(uint32_t a, uint32_t b, uint32_t c) {
  // c ? b : a, bitwise
  uint32_t d;
  asm("lop3.b32 %0, %1, %2, %3, 0xD8;" : "=r"(d) : "r"(a), "r"(b), "r"(c));
  return d;
}

__device__ __forceinline__ void decode_old(uint32_t lw0, uint32_t lw1, uint32_t nw, uint32_t base4, uint32_t* r) {
  uint32_t ha = lop3_sel(nw & 0x07070707u, nw << 4, 0x80808080u) + base4;
  uint32_t hb = lop3_sel((nw >> 4) & 0x07070707u, nw, 0x80808080u) + base4;
  r[0] = prmt(lw0, ha, 0x5140);
  r[1] = prmt(lw0, ha, 0x7362);
  r[2] = prmt(lw1, hb, 0x5140);
  r[3] = prmt(lw1, hb, 0x7362);
}

// Sign-bit layout and decoder adapted from the pinned MIT Nathen decodediet
// component already embedded in this parent, now applied to SK2 fragments.
__device__ __forceinline__ void decode_new(uint32_t lw0, uint32_t lw1, uint32_t nw, uint32_t base4, uint32_t* r) {
  uint32_t rotated;
  asm("shf.r.wrap.b32 %0, %1, %1, 4;" : "=r"(rotated) : "r"(nw));
  const uint32_t ha = (nw & 0x87878787u) + base4;
  const uint32_t hb = (rotated & 0x87878787u) + base4;
  r[0] = prmt(lw0, ha, 0x5140);
  r[1] = prmt(lw0, ha, 0x7362);
  r[2] = prmt(lw1, hb, 0x5140);
  r[3] = prmt(lw1, hb, 0x7362);
}

extern "C" __global__ void old_probe(const uint4* in, uint4* out) {
 int i=threadIdx.x+blockIdx.x*blockDim.x;uint4 v=in[i];uint32_t r[4];
 decode_old(v.x,v.y,v.z,v.w,r);out[i]=make_uint4(r[0],r[1],r[2],r[3]);
}

extern "C" __global__ void new_probe(const uint4* in, uint4* out) {
 int i=threadIdx.x+blockIdx.x*blockDim.x;uint4 v=in[i];uint32_t r[4];
 decode_new(v.x,v.y,v.z,v.w,r);out[i]=make_uint4(r[0],r[1],r[2],r[3]);
}
